package main

import (
	"errors"
	"fmt"

	"github.com/gin-gonic/gin"
)

type TestErr string

func (e TestErr) Error() string { return string(e) }

func chk(name string, ok bool) {
	status := "FAIL"
	if ok {
		status = "ok  "
	}
	fmt.Printf("%s %s\n", status, name)
}

func main() {
	inner := TestErr("some error")

	// 1. pointer Error wrapped by fmt
	err := fmt.Errorf("wrapped: %w", &gin.Error{Err: inner, Type: gin.ErrorTypeAny})
	chk("errors.Is(fmt-wrapped *Error, inner)", errors.Is(err, inner))
	var te TestErr
	chk("errors.As(fmt-wrapped *Error, &TestErr)", errors.As(err, &te))

	// 2. errors.Unwrap directly
	pe := &gin.Error{Err: inner, Type: gin.ErrorTypeAny}
	chk("errors.Unwrap(*Error) == inner", errors.Unwrap(pe) == inner)
	chk("errors.Is(*Error, inner)", errors.Is(pe, inner))

	// 3. value Error
	ve := gin.Error{Err: inner, Type: gin.ErrorTypeAny}
	chk("errors.Unwrap(Error value) == inner", errors.Unwrap(ve) == inner)
	chk("errors.Is(Error value, inner)", errors.Is(ve, inner))
	chk("errors.As(Error value, &TestErr)", errors.As(ve, &te))

	// 4. errors.As to *gin.Error
	var ge *gin.Error
	chk("errors.As(fmt-wrapped, &*gin.Error)", errors.As(err, &ge))

	// 5. gin.Error as error interface (pointer)
	var e1 error = pe
	chk("errors.Unwrap(error(*Error)) == inner", errors.Unwrap(e1) == inner)

	// 6. gin.Error as error interface (value)
	var e2 error = ve
	chk("errors.Unwrap(error(Error)) == inner", errors.Unwrap(e2) == inner)

	// 7. Unwrap method presence
	type unwrapper interface{ Unwrap() error }
	_, pok := interface{}(pe).(unwrapper)
	_, vok := interface{}(ve).(unwrapper)
	chk("*Error implements Unwrap()", pok)
	chk("Error value implements Unwrap()", vok)

	// 8. IsType / ByType sanity
	chk("IsType(ErrorTypeAny)", pe.IsType(gin.ErrorTypeAny))
}
EOF
