import re, sys, difflib

def parse(fn):
    funcs={}
    cur=None
    for line in open(fn, errors='replace'):
        line=line.rstrip('\n')
        m=re.match(r'^TEXT (\S+)', line)
        if m:
            cur=m.group(1); funcs[cur]=[]; continue
        if cur is None: continue
        if line.strip()=='':
            cur=None; continue
        funcs[cur].append(line)
    return funcs

def norm_line(line):
    parts=[p for p in line.split('\t') if p.strip()!='']
    if len(parts)<3:
        return None
    src=parts[0]
    body=' '.join(parts[3:]) if len(parts)>3 else ''
    if not body:
        body=' '.join(parts[2:])
    body=re.sub(r'0x[0-9a-f]+','H',body)
    # canonicalize call targets
    m=re.search(r'R_CALL:(\S+)', body)
    if m:
        body=re.sub(r'CALL H(\s+\[[^\]]*\])?.*$','CALL '+m.group(1),body)
    m=re.search(r'R_USEIFACE(METHOD)?:(\S+)', body)
    if m:
        body=re.sub(r'\[[^\]]*R_USEIFACE[^\]]*\]','',body)
    m=re.search(r'R_PCREL:(\S+)', body)
    if m:
        sym=m.group(1).split('+')[0]
        body=re.sub(r'0\(IP\)\s*\[[^\]]*\]','SYM:'+sym,body)
    body=re.sub(r'R_ADDR\S*','',body)
    body=re.sub(r'\[[^\]]*\]','',body)
    body=re.sub(r'\s+',' ',body).strip()
    return (src, body)

