package gin

import (
	"fmt"
	"math/rand"
	"sort"
	"strings"
	"testing"
)

type refRoute struct {
	pattern string
	segs    []string
}

func splitSegs(p string) []string {
	// absolute path: leading "" segment
	return strings.Split(p, "/")
}

// match returns params if the route matches the path
func matchRoute(segs []string, pathSegs []string) ([]Param, bool) {
	var params []Param
	i := 0
	for ; i < len(segs); i++ {
		s := segs[i]
		if strings.HasPrefix(s, "*") {
			// catch-all: matches rest, value includes leading '/'
			rest := strings.Join(pathSegs[i:], "/")
			if i > 0 {
				rest = "/" + rest
			}
			params = append(params, Param{Key: s[1:], Value: rest})
			return params, true
		}
		if i >= len(pathSegs) {
			return nil, false
		}
		if strings.HasPrefix(s, ":") {
			params = append(params, Param{Key: s[1:], Value: pathSegs[i]})
			continue
		}
		if s != pathSegs[i] {
			return nil, false
		}
	}
	if i != len(pathSegs) {
		return nil, false
	}
	return params, true
}

func spec(s string) int {
	if strings.HasPrefix(s, "*") {
		return 0
	}
	if strings.HasPrefix(s, ":") {
		return 1
	}
	return 2
}

func moreSpecific(a, b []string) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		sa, sb := spec(a[i]), spec(b[i])
		if sa != sb {
			return sa > sb
		}
	}
	return len(a) > len(b)
}

func TestFuzzParams(t *testing.T) {
	rnd := rand.New(rand.NewSource(42))
	staticWords := []string{"a", "b", "c", "ab", "abc", "x"}
	genSeg := func() string {
		switch rnd.Intn(4) {
		case 0:
			return ":" + string(rune('p'+rnd.Intn(3)))
		case 1:
			return staticWords[rnd.Intn(len(staticWords))]
		default:
			return staticWords[rnd.Intn(len(staticWords))]
		}
	}
	mismatches := 0
	for iter := 0; iter < 4000; iter++ {
		nRoutes := 1 + rnd.Intn(4)
		var routes []string
		seen := map[string]bool{}
		for r := 0; r < nRoutes; r++ {
			nSeg := 1 + rnd.Intn(3)
			parts := make([]string, nSeg)
			for i := range parts {
				parts[i] = genSeg()
			}
			// dedupe param names per route
			names := map[string]int{}
			for i, p := range parts {
				if strings.HasPrefix(p, ":") {
					names[p]++
					if names[p] > 1 {
						parts[i] = fmt.Sprintf(":%s%d", p[1:], names[p])
					}
				}
			}
			rt := "/" + strings.Join(parts, "/")
			if seen[rt] {
				continue
			}
			seen[rt] = true
			routes = append(routes, rt)
		}
		sort.Strings(routes)
		tree := &node{}
		ok := true
		for _, rt := range routes {
			func() {
				defer func() {
					if e := recover(); e != nil {
						ok = false
					}
				}()
				tree.addRoute(rt, fakeHandler(rt))
			}()
		}
		if !ok {
			continue // conflicts, skip
		}
		// requests
		for q := 0; q < 6; q++ {
			nSeg := 1 + rnd.Intn(4)
			parts := make([]string, nSeg)
			for i := range parts {
				parts[i] = staticWords[rnd.Intn(len(staticWords))]
			}
			path := "/" + strings.Join(parts, "/")
			pathSegs := splitSegs(path)

			// reference
			best := ""
			var bestParams []Param
			for _, rt := range routes {
				ps, m := matchRoute(splitSegs(rt), pathSegs)
				if !m {
					continue
				}
				if best == "" || moreSpecific(splitSegs(rt), splitSegs(best)) {
					best = rt
					bestParams = ps
				}
			}

			// gin
			v := tree.getValue(path, getParams(), getSkippedNodes(), false)
			gotRoute := ""
			if v.handlers != nil {
				v.handlers[0](nil)
				gotRoute = fakeHandlerValue
			}
			var gotParams []Param
			if v.params != nil {
				gotParams = *v.params
			}
			if gotRoute != best || fmt.Sprint(gotParams) != fmt.Sprint(bestParams) {
				mismatches++
				if mismatches < 25 {
					t.Errorf("MISMATCH routes=%v path=%q: gin route=%q params=%v ; ref route=%q params=%v",
						routes, path, gotRoute, gotParams, best, bestParams)
				}
			}
		}
	}
	t.Logf("total mismatches: %d", mismatches)
}
